import sys


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        name, start_time, end_time = parts
        start = minutes(start_time)
        end = minutes(end_time)
        if end <= start:
            worked = 0
        else:
            worked = end - start
        if worked > 6 * 60:
            if worked > 9 * 60:
                worked -= 45
            else:
                worked -= 30
        if name not in totals:
            totals[name] = worked
        else:
            totals[name] += worked

    sorted_names = sorted(totals.keys())
    for name in sorted_names:
        total_minutes = totals[name]
        hours = total_minutes // 60
        minutes = total_minutes % 60
        print(f"{name} {hours:02d}:{minutes:02d}")


if __name__ == "__main__":
    main()
